import{_ as i,o as e,c as r,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"CDS G/H (Day 1) - librados review","description":"","frontmatter":{"title":"CDS G/H (Day 1) - librados review","date":"2014-06-24T00:00:00.000Z","updated":"2014-06-25T00:00:00.000Z","tags":["[Ceph]","[librados]","[分布式存储]","[开发流程]","[性能优化]"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_G_H_Day_1_-_librados_review.md","filePath":"posts/2014/CDS_G_H_Day_1_-_librados_review.md","lastUpdated":1780459816000}'),a={name:"posts/2014/CDS_G_H_Day_1_-_librados_review.md"};function s(o,l,n,_,p,u){return e(),r("div",null,[...l[0]||(l[0]=[t('<p><strong>会议纪要</strong></p><p><strong>会议主题</strong>： Ceph 分布式存储项目会议，重点讨论了 Librados 代码库的审查、开发流程、技术领导角色的引入、发布周期以及 OSD 审查。</p><p><strong>会议关键细节</strong>：</p><ul><li><strong>开发流程与参与方式</strong>： <ul><li>通过邮件列表（如 <a href="mailto:self-dev@ceph.com" target="_blank" rel="noreferrer">self-dev@ceph.com</a>、calamari-dev@ceph.com、packaging-maintainers@ceph.com）和 IRC（irc.otc.net）参与开发讨论。</li><li>使用 GitHub 提交代码和 pull request。</li><li>利用 feature tracker 寻找工作机会并报告 bug。</li><li>引入技术领导角色，负责代码审查、优先级排序和项目方向。</li><li>关键人员包括 Sam Jess、Josh Durkin、Yehuda、Greg、Jung Yan、Gregory Amino、Zach、Deza 和 Gilham Electron 等。</li><li>测试基础设施包括 Get 和 Popit。</li></ul></li><li><strong>发布周期</strong>： <ul><li>过去采用每季度一次的命名版本发布，包含两个月编码和一个月 QA。</li><li>最近采用每季度一次的 Firefighter 版本，时间表因新功能集成挑战而延迟。</li><li>未来考虑采用定期发布，稳定现有功能，不急于合并新功能。</li><li>是否继续每季度一次的命名发布存在争议，需要进一步讨论。</li></ul></li><li><strong>Liberatos 审查</strong>： <ul><li>内部线程模型更改，提高 IOPS 性能。</li><li>并行读取，减少延迟。</li><li>跟踪，捕获和回放 Liberatos 级别的跟踪。</li></ul></li><li><strong>OSD 审查</strong>： <ul><li>会议中未详细讨论，需要进一步了解。</li></ul></li></ul><p><strong>讨论的主要议题</strong>：</p><ul><li>如何吸引更多开发者参与 Ceph 项目。</li><li>引入技术领导角色，明确责任和职责。</li><li>确定发布周期，平衡稳定性和新功能。</li><li>改进 Liberatos 和 OSD 的性能和功能。</li></ul><p><strong>决定的事项</strong>：</p><ul><li>继续讨论发布周期，并在邮件列表上提出意见。</li><li>继续推进 Liberatos 和 OSD 的改进工作。</li><li>鼓励更多开发者参与 Ceph 项目。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>继续讨论发布周期，并在邮件列表上提出意见。</li><li>完成 Liberatos 和 OSD 的改进工作。</li><li>鼓励更多开发者参与 Ceph 项目，并为他们提供支持。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到的一些英文关键词： <ul><li>Ceph</li><li>Liberatos</li><li>OSD</li><li>Rados</li><li>Calamari</li><li>GitHub</li><li>pull request</li><li>feature tracker</li><li>CI/CD</li><li>IOPS</li><li>latency</li><li>consistency</li><li>scrubbing</li><li>repair</li><li>blueprint</li><li>trace</li><li>replay</li></ul></li></ul>',12)])])}const d=i(a,[["render",s]]);export{g as __pageData,d as default};
